package pe.edu.upeu.casaonada.orden.domain;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="detalle_orden") public class DetalleOrden { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="orden_id",nullable=false) private Orden orden; @Column(name="propiedad_id",nullable=false) private Long propiedadId; @Column(nullable=false,length=160) private String concepto; @Column(name="precio_acordado",nullable=false,precision=14,scale=2) private BigDecimal precioAcordado; public Long getId(){return id;} public Orden getOrden(){return orden;} public void setOrden(Orden v){orden=v;} public Long getPropiedadId(){return propiedadId;} public void setPropiedadId(Long v){propiedadId=v;} public String getConcepto(){return concepto;} public void setConcepto(String v){concepto=v;} public BigDecimal getPrecioAcordado(){return precioAcordado;} public void setPrecioAcordado(BigDecimal v){precioAcordado=v;} }
